{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.ArrayInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "type",
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "oneOf": [
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "developer"
        }
      },
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "system"
        }
      },
      "$ref": "agent.completions.message.SystemMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "user"
        }
      },
      "$ref": "agent.completions.message.UserMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "assistant"
        }
      },
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "required": [
        "role"
      ]
    },
    {
      "type": "object",
      "properties": {
        "role": {
          "type": "string",
          "const": "tool"
        }
      },
      "$ref": "agent.completions.message.ToolMessageExpression",
      "required": [
        "role"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContent",
  "description": "Rich content for user/assistant messages (supports multimodal input).",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content (text, images, audio, video, files).",
      "type": "array",
      "items": {
        "$ref": "agent.completions.message.RichContentPart"
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  },
  "required": [
    "data",
    "format"
  ]
}
